  // Every attribute optional or defaulted — CloudKit has no required columns
  var title: String = ""
  var body: String = ""
  var updatedAt: Date = Date()

  // Relationship must be optional and have an inverse
  @Relationship(deleteRule: .cascade, inverse: \Attachment.note)
  var attachments: [Attachment]? = []

  init(title: String = "") { self.title = title }
}

let configuration = ModelConfiguration(
  "Notes",
  cloudKitDatabase: .private("iCloud.com.example.notes")
)
let container = try ModelContainer(for: Note.self, configurations: configuration)

// De-duplication is now yours: unique constraints cannot be used with CloudKit
func deduplicate(_ context: ModelContext) throws {
  let all = try context.fetch(FetchDescriptor<Note>(sortBy: [SortDescriptor(\.updatedAt)]))
  var seen: Set<String> = []
  for note in all where !seen.insert(note.title).inserted {
    context.delete(note)
  }
  try context.save()
}

