import Testing
import SwiftData

@MainActor
private func makeContainer() throws -> ModelContainer {
  let configuration = ModelConfiguration(isStoredInMemoryOnly: true)
  return try ModelContainer(for: Note.self, Folder.self, configurations: configuration)
}

@MainActor
@Test func searchMatchesTitleCaseInsensitively() throws {
  let context = try makeContainer().mainContext
  context.insert(Note(title: "Groceries"))
  context.insert(Note(title: "gardening"))

  let descriptor = FetchDescriptor<Note>(
    predicate: #Predicate { $0.title.localizedStandardContains("g") }
  )
  #expect(try context.fetchCount(descriptor) == 2)
}

@MainActor
@Test func deletingFolderCascadesToNotes() throws {
  let context = try makeContainer().mainContext
  let folder = Folder(name: "Work")
  folder.notes = [Note(title: "Standup")]
  context.insert(folder)
  context.delete(folder)
  try context.save()

  #expect(try context.fetchCount(FetchDescriptor<Note>()) == 0)
}

