@Model
final class Message {
  #Index<Message>([\.sentAt], [\.folderName, \.sentAt])
  var subject: String
  var sentAt: Date
  var isUnread: Bool
  var folderName: String        // denormalised so the cell never faults a relationship
  init(subject: String, sentAt: Date, isUnread: Bool, folderName: String) {
    self.subject = subject; self.sentAt = sentAt
    self.isUnread = isUnread; self.folderName = folderName
  }
}

