@Model
final class Playlist {
  var name: String

  // Owning side cascades: deleting the playlist deletes its entries
  @Relationship(deleteRule: .cascade, inverse: \Entry.playlist)
  var entries: [Entry] = []

  var entryCount: Int = 0        // stored, so a list row never faults the relationship

  init(name: String) { self.name = name }
}

@Model
final class Entry {
  var position: Int              // many-to-many keeps no order for you
  var playlist: Playlist?

  // Nullify: removing an entry must never delete the track itself
  @Relationship(deleteRule: .nullify)
  var track: Track?

  init(position: Int) { self.position = position }
}

@Model
final class Track {
  var title: String
  init(title: String) { self.title = title }
}

